sql_A:
SELECT round(avg(amount), 2)
FROM orders
WHERE order_date BETWEEN '2025-01-01' AND '2025-12-31';

SELECT order_id
FROM orders
WHERE amount > (SELECT AVG(amount) FROM orders);

sql_B:
SELECT DISTINCT c.name FROM customers c
WHERE EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.customer_id AND strftime('%Y', o.order_date) = '2025')
AND NOT EXISTS (SELECT 1 FROM orders o2 WHERE o2.customer_id = c.customer_id AND strftime('%Y', o2.order_date) = '2026');

SELECT name FROM customers WHERE customer_id IN (
  SELECT customer_id FROM orders WHERE order_date LIKE '2026-%' GROUP BY customer_id HAVING COUNT(*) = (
    SELECT MAX(cnt) FROM (
      SELECT customer_id, COUNT(*) AS cnt FROM orders WHERE order_date LIKE '2026-%' GROUP BY customer_id
    )
  )
);

